#!/bin/bash
# Copies the template contract from a budstack-saas checkout into this skill.
#
# The contract is generated by the platform (nextjs_space/scripts/
# export-template-contract.ts) from the code that renders templates. The skill
# builds and validates templates against these four files and nothing else, so
# run this whenever budstack-saas changes its sections or design-system schema.
#
# Usage:
#   scripts/sync-contract.sh <path-to-budstack-saas>
set -euo pipefail

if [ "$#" -ne 1 ]; then
  echo "usage: scripts/sync-contract.sh <path-to-budstack-saas>" >&2
  exit 2
fi

SRC="$1/docs/templates/contract"
DEST="$(cd "$(dirname "$0")/.." && pwd)/references/contract"
FILES="section-schemas.json design-system.schema.json registry.json component-catalog.md"

for file in $FILES; do
  if [ ! -f "$SRC/$file" ]; then
    echo "sync-contract: $SRC/$file not found — is that a budstack-saas checkout with the contract generated?" >&2
    exit 1
  fi
done

mkdir -p "$DEST"
for file in $FILES; do
  cp "$SRC/$file" "$DEST/$file"
done
echo "sync-contract: copied 4 files to $DEST"
